import { Inject, Injectable, Optional } from "@angular/core";
import { HttpClient, HttpHeaders } from "@angular/common/http";
import { Observable, of, throwError } from "rxjs";
import { catchError, map, tap } from "rxjs/operators";
import {
  AMIGO_AUTH_TOKEN_PROVIDER,
  AmigoAuthTokenProvider,
} from "./auth-token.provider";
import { AMIGO_FORM_CONFIG, AmigoFormConfig } from "./config";
import {
  FormFieldOption,
  FormFieldOptionGroup,
  FormFieldSchema,
  SelectOptionsApiConfig,
  SelectOptionsSourceSchema,
} from "./models";

@Injectable({ providedIn: "root" })
export class AmigoSelectOptionsService {
  private cache = new Map<string, FormFieldOption[] | FormFieldOptionGroup[]>();
  private rawCache = new Map<string, any>();

  constructor(
    private http: HttpClient,
    @Optional() @Inject(AMIGO_FORM_CONFIG) private cfg: AmigoFormConfig | null,
    @Optional()
    @Inject(AMIGO_AUTH_TOKEN_PROVIDER)
    private tokenProvider: AmigoAuthTokenProvider | null,
  ) {}

  load(
    field: FormFieldSchema,
    _formValue?: Record<string, any>,
    parentValuesMap?: Record<string, any>,
  ): Observable<FormFieldOption[] | FormFieldOptionGroup[]> {
    console.log(`[AmigoSelectOptionsService] load called for field: ${field.id}, parentValuesMap:`, parentValuesMap);
    const api = field.optionsSource?.api;
    if (!api?.url) {
      console.log(`[AmigoSelectOptionsService] No api.url found for field: ${field.id}. Returning empty.`);
      return of([]);
    }

    let rawUrl = api.url;
    console.log(`[AmigoSelectOptionsService] Raw URL:`, rawUrl);

    if (field.dependentSelect?.type === "api" && parentValuesMap) {
      const parents = [];
      if (field.dependentSelect.parentFieldId) parents.push(field.dependentSelect);
      for (const ap of field.dependentSelect.additionalParents || []) {
        parents.push(ap);
      }

      for (const p of parents) {
        let val = parentValuesMap[p.parentFieldId];
        if (val === undefined || val === null) continue;
        
        val = this.capitalize(val);

        if (p.urlPlaceholder) {
          console.log(`[AmigoSelectOptionsService] Replacing placeholder ${p.urlPlaceholder} with ${val}`);
          rawUrl = rawUrl.replace(p.urlPlaceholder, encodeURIComponent(String(val)));
        }
      }
    }

    let url = this.resolveUrl(rawUrl);
    console.log(`[AmigoSelectOptionsService] Resolved URL before query params:`, url);

    if (field.dependentSelect?.type === "api" && parentValuesMap) {
      const parents = [];
      if (field.dependentSelect.parentFieldId) parents.push(field.dependentSelect);
      for (const ap of field.dependentSelect.additionalParents || []) {
        parents.push(ap);
      }

      for (const p of parents) {
        let val = parentValuesMap[p.parentFieldId];
        if (val === undefined || val === null) continue;
        
        val = this.capitalize(val);

        if (p.queryParamName) {
          const separator = url.includes("?") ? "&" : "?";
          url = `${url}${separator}${p.queryParamName}=${encodeURIComponent(String(val))}`;
          console.log(`[AmigoSelectOptionsService] Appended query parameter:`, url);
        }
      }
    }

    const cacheKey = `${field.id}::${api.method || "GET"}::${url}`;
    const cached = this.cache.get(cacheKey);
    if (cached) return of(cached);

    const method = ((api.method || "GET") as string).toUpperCase();

    const shouldBearer = api.secured === true && api.authType === "BEARER";

    let headers = new HttpHeaders();
    if (!shouldBearer) {
      headers = headers.set("X-Amigo-Skip-Auth", "1");
    } else {
      const token = this.resolveToken(api);
      if (token) headers = headers.set("Authorization", `Bearer ${token}`);
    }

    return this.http.request(method, url, { headers }).pipe(
      tap((res: any) => this.rawCache.set(field.id, res)),
      map((res: any) => this.mapOptions(res, api)),
      tap((opts) => this.cache.set(cacheKey, opts)),
      catchError((err) => {
        const msg =
          err?.error?.message || err?.message || "Failed to load options.";
        return throwError(() => new Error(msg));
      }),
    );
  }

  clear(fieldId?: string): void {
    if (!fieldId) {
      this.cache.clear();
      this.rawCache.clear();
      return;
    }
    for (const k of [...this.cache.keys()]) {
      if (k.startsWith(fieldId + "::")) this.cache.delete(k);
    }
    this.rawCache.delete(fieldId);
  }

  getRawResponse(fieldId: string): any {
    return this.rawCache.get(fieldId) ?? null;
  }

  private capitalize(val: any): string {
    console.log(`[AmigoSelectOptionsService] capitalize input:`, val, typeof val);
    if (Array.isArray(val) && val.length > 0) {
      val = val[0];
    }
    if (typeof val !== "string") val = String(val);
    if (!val) return val;
    const result = val.charAt(0).toUpperCase() + val.slice(1);
    console.log(`[AmigoSelectOptionsService] capitalize output:`, result);
    return result;
  }

  private resolveUrl(url: string): string {
    const u = (url || "").trim().replace(/^['"]+|['"]+$/g, "");
    if (!u) return u;
    if (/^https?:\/\//i.test(u)) return u;

    // Use selectOptionsBaseUrl if available, otherwise fall back into apiBaseUrl
    const base = (
      this.cfg?.selectOptionsBaseUrl ||
      this.cfg?.apiBaseUrl ||
      ""
    ).replace(/\/+$/, "");

    if (!base) return u.startsWith("/") ? u : "/" + u;
    if (u.startsWith("/")) return base + u;
    return base + "/" + u;
  }

  private resolveToken(api: SelectOptionsApiConfig): string | null {
    const key = api.tokenKey || "access_token";
    if (api.tokenFrom === "SESSION_STORAGE") {
      return sessionStorage.getItem(key);
    }
    if (api.tokenFrom === "LOCAL_STORAGE" || !api.tokenFrom) {
      return localStorage.getItem(key);
    }
    if (api.tokenFrom === "CUSTOM_CALLBACK") {
      return this.tokenProvider?.() || null;
    }
    return null;
  }

  private mapOptions(res: any, api: SelectOptionsApiConfig): FormFieldOption[] | FormFieldOptionGroup[] {
    const rm = api.responseMapping;
    const labelKey = rm?.labelKey || "label";
    const valueKey = rm?.valueKey || "value";
    const data = rm?.dataPath ? this.getByPath(res, rm.dataPath) : res;

    if (data && typeof data === 'object' && !Array.isArray(data)) {
      // Data is an object, map it to option groups
      const groups: FormFieldOptionGroup[] = [];
      for (const [key, value] of Object.entries(data)) {
        if (Array.isArray(value)) {
          const groupLabel = this.formatGroupLabel(key);
          const options = value.map((item: any) => ({
            label: item?.[labelKey] ?? "",
            value: item?.[valueKey],
          })).filter((o: any) => o.label !== "" && o.value !== undefined);
          
          if (options.length > 0) {
            groups.push({ groupLabel, options });
          }
        }
      }
      return groups;
    }

    const arr = Array.isArray(data)
      ? data
      : Array.isArray(data?.items)
        ? data.items
        : [];

    return arr
      .map((item: any) => ({
        label: item?.[labelKey] ?? "",
        value: item?.[valueKey],
      }))
      .filter((o: any) => o.label !== "" && o.value !== undefined);
  }

  private formatGroupLabel(key: string): string {
    // Convert camelCase or snake_case to Title Case
    return key
      .replace(/([A-Z])/g, ' $1') // insert space before capital letters
      .replace(/_/g, ' ') // replace underscores with spaces
      .replace(/^./, str => str.toUpperCase()) // capitalize first letter
      .trim();
  }

  private getByPath(obj: any, path: string): any {
    if (!obj || !path) return obj;
    return path
      .split(".")
      .reduce((acc, k) => (acc == null ? undefined : acc[k]), obj);
  }
}
